components.css:
.ds-stato{display:grid;grid-template-columns:1.15fr 1fr;gap:28px;align-items:stretch}
@media (max-width:820px){.ds-stato{grid-template-columns:1fr;gap:20px}}
.ds-stato-manca{display:block;text-decoration:none;color:inherit;background:#fffdf9;border:1px solid #e2d9c6;border-left:7px solid #9A3412;border-radius:26px;box-shadow:0 10px 30px rgba(20,20,20,.10);padding:26px 30px 24px;transition:transform .35s cubic-bezier(.16,1,.3,1),box-shadow .35s ease,border-color .35s ease}
.ds-stato-manca:hover{transform:translateY(-4px);box-shadow:0 24px 60px rgba(20,20,20,.22);border-color:#9A3412}
.ds-sm-titolo{margin:0;font-weight:400}
.ds-sm-num{display:block;font-family:'Bebas Neue',Impact,sans-serif;font-size:clamp(5rem,13vw,10rem);line-height:.78;color:#9A3412}
.ds-sm-testa{display:block;font-family:'Bebas Neue',Impact,sans-serif;text-transform:uppercase;font-size:clamp(1.3rem,3.4vw,2.1rem);line-height:1.05;color:#16362a;margin-top:8px}
.ds-sm-det{margin:14px 0 0;font-size:1rem;line-height:1.65;color:#5b6a61;max-width:46ch}
.ds-sm-cta{display:inline-block;margin-top:16px;font-weight:700;font-size:.88rem;color:#9A3412}
.ds-stato-fatto{align-self:center}
.ds-sf-tit{font-family:'Bebas Neue',Impact,sans-serif;text-transform:uppercase;font-weight:400;font-size:1.35rem;letter-spacing:.04em;color:#5b6a61;margin:0 0 16px}
.ds-stat{display:flex;align-items:baseline;gap:10px;margin-bottom:14px}
.ds-num{font-family:'Bebas Neue',Impact,sans-serif;font-size:2.6rem;color:#8A6B00;line-height:1}
.ds-unit{font-size:1rem;color:#5b6a61}
